insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('deliverables','deliverables',false,26214400,array['application/pdf','image/png','image/jpeg','text/plain','text/csv','application/zip','application/octet-stream','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','application/vnd.openxmlformats-officedocument.wordprocessingml.document']) on conflict(id) do nothing;
create policy evidence_upload on storage.objects for insert to authenticated with check(bucket_id='deliverables' and (storage.foldername(name))[2]=auth.uid()::text and public.can_work((storage.foldername(name))[1]));
create policy evidence_read on storage.objects for select to authenticated using(bucket_id='deliverables' and public.can_work((storage.foldername(name))[1]));
create policy evidence_cleanup on storage.objects for delete to authenticated using(bucket_id='deliverables' and owner_id=auth.uid()::text and not exists(select 1 from public.deliverables d where d.file_path=name));
